* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  background: #f5f7fa;
  color: #333;
}

h1 {
  text-align: center;
  padding: 20px 0 10px;
  font-size: 24px;
  color: #2c3e50;
}

.container {
  display: flex;
  gap: 24px;
  padding: 10px 24px 24px;
  max-width: 1600px;
  margin: 0 auto;
  align-items: flex-start;
}

/* Bubble Chart Panel */
.chart-panel {
  flex: 1 1 55%;
  background: #fff;
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.1);
  padding: 16px;
  min-width: 0;
}

.chart-panel h2 {
  font-size: 16px;
  color: #555;
  margin-bottom: 8px;
}

#bubble-chart {
  width: 100%;
  position: relative;
}

#bubble-chart svg {
  display: block;
  width: 100%;
  height: auto;
}

/* Legends */
.legend-container {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 16px;
  margin-top: 10px;
  padding: 8px 0;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: #555;
  cursor: default;
}

.legend-swatch {
  width: 14px;
  height: 14px;
  border-radius: 3px;
  flex-shrink: 0;
}

/* Tooltip */
.tooltip {
  position: absolute;
  pointer-events: none;
  background: rgba(0, 0, 0, 0.85);
  color: #fff;
  padding: 10px 14px;
  border-radius: 6px;
  font-size: 13px;
  line-height: 1.5;
  max-width: 280px;
  z-index: 1000;
  opacity: 0;
  transition: opacity 0.15s ease;
}

.tooltip .tt-ticker {
  font-weight: 700;
  font-size: 15px;
  margin-bottom: 2px;
}

.tooltip .tt-name {
  color: #ccc;
}

.tooltip .tt-sector {
  color: #aaa;
  font-style: italic;
}

/* Table Panel */
.table-panel {
  flex: 1 1 45%;
  background: #fff;
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.1);
  padding: 16px;
  min-width: 0;
  max-height: 680px;
  overflow-y: auto;
}

.table-panel h2 {
  font-size: 16px;
  color: #555;
  margin-bottom: 8px;
}

#stock-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

#stock-table thead th {
  position: sticky;
  top: 0;
  background: #f0f3f7;
  padding: 10px 12px;
  text-align: left;
  font-weight: 600;
  color: #444;
  border-bottom: 2px solid #ddd;
  white-space: nowrap;
}

#stock-table tbody td {
  padding: 8px 12px;
  border-bottom: 1px solid #eee;
}

#stock-table tbody tr {
  cursor: pointer;
  transition: background 0.15s ease;
}

#stock-table tbody tr:hover {
  background: #f0f6ff;
}

#stock-table tbody tr.highlighted {
  background: #d4e8ff;
  font-weight: 600;
}

/* Bubble selection styling */
.bubble-selected {
  stroke: #333;
  stroke-width: 3px;
}

