(function () {
  "use strict";

  const WIDTH = 720;
  const HEIGHT = 620;
  const ETF_RADIUS = 18;

  // Sector color palette
  const sectorColors = {
    "Information Technology": "#4e79a7",
    "Industry": "#f28e2b",
    "Energy": "#e15759",
    "Financial": "#76b7b2",
    "ETF": "#999999"
  };

  // Format market cap for display
  function formatMarketCap(val) {
    if (val == null || val === "" || isNaN(+val)) return "—";
    const num = +val;
    if (num >= 1e12) return (num / 1e12).toFixed(2) + "T";
    if (num >= 1e9) return (num / 1e9).toFixed(2) + "B";
    if (num >= 1e6) return (num / 1e6).toFixed(2) + "M";
    return num.toLocaleString();
  }

  // Sector center positions for force-directed clustering
  const sectorCenters = {
    "Information Technology": { x: WIDTH * 0.3, y: HEIGHT * 0.35 },
    "Industry": { x: WIDTH * 0.7, y: HEIGHT * 0.35 },
    "Energy": { x: WIDTH * 0.3, y: HEIGHT * 0.7 },
    "Financial": { x: WIDTH * 0.7, y: HEIGHT * 0.7 },
    "ETF": { x: WIDTH * 0.5, y: HEIGHT * 0.52 }
  };

  // Radius scale for market cap
  function buildRadiusScale(data) {
    const caps = data
      .filter(d => d.sector !== "ETF" && d.marketCap > 0)
      .map(d => d.marketCap);
    return d3.scaleSqrt()
      .domain([d3.min(caps), d3.max(caps)])
      .range([12, 60]);
  }

  // Parse CSV
  d3.csv("data/stock-descriptions.csv").then(function (raw) {
    const data = raw.map(d => ({
      ticker: d.ticker,
      name: d["full name"],
      sector: d.sector,
      marketCap: d.marketCap ? +d.marketCap : null,
      country: d.country || null,
      website: d.website || null
    }));

    const rScale = buildRadiusScale(data);

    // Assign radii
    data.forEach(d => {
      d.isETF = d.sector === "ETF";
      d.r = d.isETF ? ETF_RADIUS : (d.marketCap ? rScale(d.marketCap) : 14);
    });

    drawBubbleChart(data, rScale);
    drawTable(data);
  });

  let selectedTicker = null;

  // ── Bubble Chart ──────────────────────────────────────────────────────
  function drawBubbleChart(data, rScale) {
    const svg = d3.select("#bubble-chart")
      .append("svg")
      .attr("viewBox", `0 0 ${WIDTH} ${HEIGHT}`)
      .attr("preserveAspectRatio", "xMidYMid meet");

    // Tooltip
    const tooltip = d3.select("body")
      .append("div")
      .attr("class", "tooltip");

    // Force simulation
    const simulation = d3.forceSimulation(data)
      .force("x", d3.forceX(d => sectorCenters[d.sector].x).strength(0.35))
      .force("y", d3.forceY(d => sectorCenters[d.sector].y).strength(0.35))
      .force("collide", d3.forceCollide(d => d.r + 2).strength(1).iterations(4))
      .force("center", d3.forceCenter(WIDTH / 2, HEIGHT / 2).strength(0.05))
      .alphaDecay(0.02)
      .on("tick", ticked);

    // Node groups
    const node = svg.selectAll(".node")
      .data(data)
      .join("g")
      .attr("class", "node")
      .style("cursor", "pointer");

    // Circles
    node.append("circle")
      .attr("r", d => d.r)
      .attr("fill", d => sectorColors[d.sector])
      .attr("fill-opacity", 0.85)
      .attr("stroke", "#fff")
      .attr("stroke-width", 1.5);

    // Labels
    node.append("text")
      .text(d => d.ticker)
      .attr("text-anchor", "middle")
      .attr("dy", "0.35em")
      .attr("font-size", d => Math.max(8, Math.min(d.r * 0.45, 14)))
      .attr("fill", "#fff")
      .attr("font-weight", "600")
      .attr("pointer-events", "none");

    // Hover events (no tooltip for ETFs)
    node
      .on("mouseenter", function (event, d) {
        if (d.isETF) return;
        tooltip
          .style("opacity", 1)
          .html(
            `<div class="tt-ticker">${d.ticker}</div>` +
            `<div class="tt-name">${d.name}</div>` +
            `<div class="tt-sector">${d.sector}</div>`
          );
      })
      .on("mousemove", function (event) {
        tooltip
          .style("left", (event.pageX + 14) + "px")
          .style("top", (event.pageY - 10) + "px");
      })
      .on("mouseleave", function () {
        tooltip.style("opacity", 0);
      });

    // Click events
    node.on("click", function (event, d) {
      selectStock(d.ticker);
    });

    function ticked() {
      node.attr("transform", d => {
        d.x = Math.max(d.r, Math.min(WIDTH - d.r, d.x));
        d.y = Math.max(d.r, Math.min(HEIGHT - d.r, d.y));
        return `translate(${d.x},${d.y})`;
      });
    }

    // Store node selection globally for highlighting
    window.__bubbleNodes = node;

    // ── Legend ─────────────────────────────────────────────────────────
    const legendContainer = d3.select("#bubble-chart")
      .append("div")
      .attr("class", "legend-container");

    const sectors = Object.keys(sectorColors);
    sectors.forEach(s => {
      const item = legendContainer.append("div").attr("class", "legend-item");
      item.append("div")
        .attr("class", "legend-swatch")
        .style("background", sectorColors[s]);
      item.append("span").text(s);
    });
  }

  // ── Data Table ────────────────────────────────────────────────────────
  function drawTable(data) {
    const table = d3.select("#stock-table");

    // Header
    const thead = table.append("thead").append("tr");
    ["Ticker Symbol", "Full Company Name", "Sector", "Market Cap"].forEach(h =>
      thead.append("th").text(h)
    );

    // Body
    const tbody = table.append("tbody");
    const rows = tbody.selectAll("tr")
      .data(data)
      .join("tr")
      .attr("data-ticker", d => d.ticker);

    rows.append("td").text(d => d.ticker);
    rows.append("td").text(d => d.name);
    rows.append("td").text(d => d.sector);
    rows.append("td").text(d => formatMarketCap(d.marketCap));

    // Click handler
    rows.on("click", function (event, d) {
      selectStock(d.ticker);
    });

    // Store for highlighting
    window.__tableRows = rows;
  }

  // ── Selection Logic ───────────────────────────────────────────────────
  function selectStock(ticker) {
    if (selectedTicker === ticker) {
      selectedTicker = null;
    } else {
      selectedTicker = ticker;
    }

    // Highlight bubble
    if (window.__bubbleNodes) {
      window.__bubbleNodes.select("circle")
        .classed("bubble-selected", d => d.ticker === selectedTicker)
        .attr("stroke", d => d.ticker === selectedTicker ? "#333" : "#fff")
        .attr("stroke-width", d => d.ticker === selectedTicker ? 3 : 1.5);
    }

    // Highlight table row & scroll into view
    if (window.__tableRows) {
      window.__tableRows.classed("highlighted", d => d.ticker === selectedTicker);

      if (selectedTicker) {
        const row = document.querySelector(`tr[data-ticker="${selectedTicker}"]`);
        if (row) {
          row.scrollIntoView({ behavior: "smooth", block: "center" });
        }
      }
    }
  }
})();

